<div class="d-flex justify-content-between mb-3"><h2>Service Order</h2><?php if(is_role('PIC Project')):?><a class="btn btn-primary" href="<?=site_url('service-orders/create')?>">+ Buat SO</a><?php endif;?></div><div class="table-responsive"><table class="table"><thead><tr><th>SO Number</th><th>Agreement</th><th>Aktivitas</th><th>Budget</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=html_escape($r->so_number)?></td><td><?=html_escape($r->agreement_number)?></td><td><?=html_escape($r->activity)?></td><td><?=rupiah($r->total_budget)?></td><td><span class="badge text-bg-<?=$r->status==='Approved'?'success':'secondary'?>"><?=$r->status?></span></td><td><?php if($r->status==='Draft'&&is_role('PIC Project')):?><a class="btn btn-sm btn-outline-primary" href="<?=site_url('service-orders/edit/'.$r->so_id)?>">Edit</a><a class="btn btn-sm btn-success" href="<?=site_url('service-orders/approve/'.$r->so_id)?>" onclick="return confirm('BP sudah menyetujui SO di luar aplikasi?')">Approve & Lock</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
